/** Msg defines the Msg service. */
export interface Msg {
  /**
   * UpdateParams defines a (governance) operation for updating the module
   * parameters. The authority defaults to the x/gov module account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /** CreateTreasury opens a new treasury. */
  CreateTreasury(request: MsgCreateTreasury): Promise<MsgCreateTreasuryResponse>;
  /** Deposit moves funds from an account into a treasury. */
  Deposit(request: MsgDeposit): Promise<MsgDepositResponse>;
  /** Spend moves funds out of a treasury to a recipient. */
  Spend(request: MsgSpend): Promise<MsgSpendResponse>;
  /** CreateLock commits treasury funds to a beneficiary on a schedule. */
  CreateLock(request: MsgCreateLock): Promise<MsgCreateLockResponse>;
  /** ClaimLock releases whatever has vested to the beneficiary. */
  ClaimLock(request: MsgClaimLock): Promise<MsgClaimLockResponse>;
  /** RevokeLock cancels a revocable lock, returning the unreleased portion. */
  RevokeLock(request: MsgRevokeLock): Promise<MsgRevokeLockResponse>;
  /** --- conditional locks (escrow) ---------------------------------------- */
  OpenEscrow(request: MsgOpenEscrow): Promise<MsgOpenEscrowResponse>;
  ReleaseEscrow(request: MsgReleaseEscrow): Promise<MsgReleaseEscrowResponse>;
  DisputeEscrow(request: MsgDisputeEscrow): Promise<MsgDisputeEscrowResponse>;
  ResolveEscrow(request: MsgResolveEscrow): Promise<MsgResolveEscrowResponse>;
  /** AssignRole grants an address a role over a treasury. */
  AssignRole(request: MsgAssignRole): Promise<MsgAssignRoleResponse>;
  /** RevokeRole removes an address's role. */
  RevokeRole(request: MsgRevokeRole): Promise<MsgRevokeRoleResponse>;
  /** SetSpendPolicy sets the spending constraints for one denom. */
  SetSpendPolicy(request: MsgSetSpendPolicy): Promise<MsgSetSpendPolicyResponse>;
  /** SetPaused freezes or unfreezes a treasury. */
  SetPaused(request: MsgSetPaused): Promise<MsgSetPausedResponse>;
  /** SetAdmin transfers administrative control of a treasury. */
  SetAdmin(request: MsgSetAdmin): Promise<MsgSetAdminResponse>;
}

